new_css='''/* Spotlight: a light behind the page, and a lit edge on each entity near the pointer */
.app { position: relative; z-index: 1; }
.spot { position: fixed; inset: 0; pointer-events: none; z-index: 0; opacity: 0; transition: opacity .4s;
  background: radial-gradient(circle 380px at var(--x, 50%) var(--y, 30%), rgba(255, 244, 228, .16), rgba(167, 139, 250, .07) 45%, transparent 75%); }
.spot.on { opacity: 1; }
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
  .lit { position: relative; background-image: radial-gradient(260px circle at var(--mx, -999px) var(--my, -999px), rgba(255, 244, 228, .08), transparent 70%); }
  .lit::after { content: ""; position: absolute; inset: -1px; padding: 1px; border-radius: inherit; pointer-events: none;
    background: radial-gradient(200px circle at var(--mx, -999px) var(--my, -999px), rgba(255, 244, 228, .75), transparent 65%);
    -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite: xor; mask-composite: exclude; }
}
'''
s=s.replace(old_css,new_css)
old_js=s[s.index('<script>\n(() => {'):s.index('</script>\n</body>')]
new_js='''<script>
(() => {
  const spot = document.querySelector('.spot');
  const lit = [...document.querySelectorAll('.card, .col, .panel, .case, .dials, .note, .step, .btn, pre')];
  lit.forEach(el => el.classList.add('lit'));
  let x = -9999, y = -9999, queued = false;
  const paint = () => {
    queued = false;
    const rects = lit.map(el => el.getBoundingClientRect());
    spot.style.setProperty('--x', x + 'px');
    spot.style.setProperty('--y', y + 'px');
    lit.forEach((el, i) => {
      el.style.setProperty('--mx', x - rects[i].left + 'px');
      el.style.setProperty('--my', y - rects[i].top + 'px');
    });
  };
  const queue = () => { if (!queued) { queued = true; requestAnimationFrame(paint); } };
  addEventListener('pointermove', e => { x = e.clientX; y = e.clientY; spot.classList.add('on'); queue(); });
  addEventListener('scroll', queue, { passive: true });
  document.addEventListener('pointerleave', () => { spot.classList.remove('on'); x = y = -9999; queue(); });
})();
'''
s=s.replace(old_js,new_js)
open(p,'w').write(s)
